ALTER TABLE public.suppliers ADD COLUMN director_position text, ADD COLUMN director_name text, ADD COLUMN director_name_dative text;
CREATE OR REPLACE FUNCTION public.can_use_trust_letters(_user uuid, _org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.user_has_permission(_user,_org,'crm.trust_letters') AND (public.user_is_org_admin(_user,_org) OR NOT EXISTS(SELECT 1 FROM public.user_permissions WHERE user_id=_user AND organization_id=_org AND permission_key='crm' AND NOT allowed)) $$;
REVOKE ALL ON FUNCTION public.can_use_trust_letters(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_use_trust_letters(uuid,uuid) TO authenticated,service_role;
CREATE TABLE public.organization_letter_settings (organization_id uuid PRIMARY KEY REFERENCES public.organizations(id) ON DELETE CASCADE, template_path text, destination text NOT NULL DEFAULT 'терминала г. Нерюнгри', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.organization_letter_settings TO authenticated;
GRANT ALL ON public.organization_letter_settings TO service_role;
ALTER TABLE public.organization_letter_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY letter_settings_read ON public.organization_letter_settings FOR SELECT TO authenticated USING(public.can_use_trust_letters(auth.uid(),organization_id));
CREATE POLICY letter_settings_insert ON public.organization_letter_settings FOR INSERT TO authenticated WITH CHECK(public.user_is_org_admin(auth.uid(),organization_id) AND (template_path IS NULL OR template_path LIKE organization_id::text || '/%'));
CREATE POLICY letter_settings_update ON public.organization_letter_settings FOR UPDATE TO authenticated USING(public.user_is_org_admin(auth.uid(),organization_id)) WITH CHECK(public.user_is_org_admin(auth.uid(),organization_id) AND (template_path IS NULL OR template_path LIKE organization_id::text || '/%'));
CREATE TABLE public.request_invoice_extracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.requests(id) ON DELETE CASCADE, file_path text NOT NULL, extracted jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, UNIQUE(request_id,file_path));
GRANT SELECT,INSERT,UPDATE ON public.request_invoice_extracts TO authenticated;
GRANT ALL ON public.request_invoice_extracts TO service_role;
ALTER TABLE public.request_invoice_extracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoice_extract_read ON public.request_invoice_extracts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id));
CREATE POLICY invoice_extract_insert ON public.request_invoice_extracts FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id AND public.can_use_trust_letters(auth.uid(),r.organization_id)));
CREATE POLICY invoice_extract_update ON public.request_invoice_extracts FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id AND public.can_use_trust_letters(auth.uid(),r.organization_id))) WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.requests r WHERE r.id=request_id AND public.can_use_trust_letters(auth.uid(),r.organization_id)));
CREATE TABLE public.trust_letters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), number text NOT NULL, created_by uuid NOT NULL, request_ids uuid[] NOT NULL, carrier text NOT NULL, payload jsonb NOT NULL, file_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,number));
GRANT SELECT ON public.trust_letters TO authenticated;
GRANT ALL ON public.trust_letters TO service_role;
ALTER TABLE public.trust_letters ENABLE ROW LEVEL SECURITY;
CREATE POLICY trust_letter_read ON public.trust_letters FOR SELECT TO authenticated USING(public.can_use_trust_letters(auth.uid(),organization_id));
CREATE OR REPLACE FUNCTION public.trust_storage_org(_name text) RETURNS uuid LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN RETURN split_part(_name,'/',1)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END $$;
CREATE POLICY letter_template_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='letter-templates' AND public.can_use_trust_letters(auth.uid(),public.trust_storage_org(name)));
CREATE POLICY letter_template_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='letter-templates' AND public.user_is_org_admin(auth.uid(),public.trust_storage_org(name)));
CREATE POLICY letter_template_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='letter-templates' AND public.user_is_org_admin(auth.uid(),public.trust_storage_org(name))) WITH CHECK(bucket_id='letter-templates' AND public.user_is_org_admin(auth.uid(),public.trust_storage_org(name)));
CREATE POLICY letter_template_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='letter-templates' AND public.user_is_org_admin(auth.uid(),public.trust_storage_org(name)));
CREATE POLICY trust_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='trust-letters' AND public.can_use_trust_letters(auth.uid(),public.trust_storage_org(name)));
CREATE POLICY trust_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='trust-letters' AND split_part(name,'/',2)=auth.uid()::text AND public.can_use_trust_letters(auth.uid(),public.trust_storage_org(name)) AND lower(name) LIKE '%.docx');
CREATE POLICY trust_file_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='trust-letters' AND split_part(name,'/',2)=auth.uid()::text AND public.can_use_trust_letters(auth.uid(),public.trust_storage_org(name)) AND NOT EXISTS(SELECT 1 FROM public.trust_letters t WHERE t.file_path=name));
CREATE OR REPLACE FUNCTION public.finalize_trust_letter(_org uuid,_requests uuid[],_carrier text,_payload jsonb,_path text) RETURNS public.trust_letters LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage AS $$
DECLARE r public.requests; result public.trust_letters; n integer; y text=to_char(now(),'YYYY'); url text;
BEGIN
 IF NOT public.can_use_trust_letters(auth.uid(),_org) THEN RAISE EXCEPTION 'Нет права на доверительные письма' USING ERRCODE='42501'; END IF;
 IF cardinality(_requests) IS NULL OR cardinality(_requests)<1 OR cardinality(_requests)>100 OR length(_carrier)>255 OR jsonb_typeof(_payload) IS DISTINCT FROM 'object' OR jsonb_typeof(_payload->'groups') IS DISTINCT FROM 'array' OR jsonb_array_length(_payload->'groups')<1 OR length(coalesce(_payload->>'addressee_name',''))=0 OR length(coalesce(_payload->>'destination',''))=0 OR (_payload->>'carrier') IS DISTINCT FROM _carrier THEN RAISE EXCEPTION 'Проверьте адресата, позиции, ТК и пункт назначения'; END IF;
 IF _path NOT LIKE _org::text||'/'||auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='trust-letters' AND name=_path AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Готовый файл не найден'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.organization_letter_settings s JOIN storage.objects o ON o.bucket_id='letter-templates' AND o.name=s.template_path WHERE s.organization_id=_org) THEN RAISE EXCEPTION 'Загрузите бланк в настройках'; END IF;
 FOR r IN SELECT * FROM public.requests WHERE id=ANY(_requests) LOOP
  IF r.organization_id<>_org OR NOT (public.user_can_view_request(auth.uid(),r.organization_id,r.applicant_user_id) OR EXISTS(SELECT 1 FROM public.clients c WHERE c.id=r.client_id AND c.user_id=auth.uid())) THEN RAISE EXCEPTION 'Нет доступа к заявке' USING ERRCODE='42501'; END IF;
  IF coalesce(trim(r.transport_company),'')='' THEN RAISE EXCEPTION 'Выберите ТК в заявке %',r.request_number; END IF;
  IF (CASE WHEN trim(r.transport_company) ~* '^ТК' THEN trim(r.transport_company) ELSE 'ТК '||trim(r.transport_company) END) <> _carrier THEN RAISE EXCEPTION 'ТК не совпадает с заявкой %',r.request_number; END IF;
 END LOOP;
 IF (SELECT count(*) FROM public.requests WHERE id=ANY(_requests) AND organization_id=_org) <> cardinality(_requests) THEN RAISE EXCEPTION 'Заявки недоступны или повторяются'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(_org::text||y));
 SELECT coalesce(max(substring(number from '[0-9]+$')::integer),0)+1 INTO n FROM public.trust_letters WHERE organization_id=_org AND number LIKE 'ДП-'||y||'-%';
 INSERT INTO public.trust_letters(organization_id,number,created_by,request_ids,carrier,payload,file_path) VALUES(_org,'ДП-'||y||'-'||CASE WHEN n<1000 THEN lpad(n::text,3,'0') ELSE n::text END,auth.uid(),_requests,_carrier,_payload,_path) RETURNING * INTO result;
 url='/storage/v1/object/authenticated/trust-letters/'||_path;
 UPDATE public.requests SET document_urls=array_append(coalesce(document_urls,'{}'::text[]),url) WHERE id=ANY(_requests);
 INSERT INTO public.request_activities(request_id,organization_id,user_id,action,description) SELECT unnest(_requests),_org,auth.uid(),'trust_letter_created','Сформировано доверительное письмо '||result.number||' ('||_carrier||')';
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.finalize_trust_letter(uuid,uuid[],text,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.finalize_trust_letter(uuid,uuid[],text,jsonb,text) TO authenticated;
